param([string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path)
$ErrorActionPreference='Stop'; $snapshotRoot=Join-Path $RepositoryRoot 'tests/e2e/frontend-operations-settlement/snapshots'; $outputPath=Join-Path $RepositoryRoot 'docs/evidence/frontend/operations-settlement-visual-baseline.json'
$snapshots=@(Get-ChildItem -LiteralPath $snapshotRoot -Filter 'PV-*.png'|Sort-Object Name); if($snapshots.Count -ne 28){throw "Expected exactly 28 settlement snapshots, found $($snapshots.Count)."}
$cases=foreach($snapshot in $snapshots){$pv=[IO.Path]::GetFileNameWithoutExtension($snapshot.Name);$number=[int]$pv.Substring(3);$pageId=if($number -le 143){'operations.clearing'}elseif($number -le 153){'operations.reconciliation'}else{'operations.eod'};[ordered]@{pv=$pv;pageId=$pageId;testId="operations-settlement-visual.spec.ts::$pv";baselinePath=$snapshot.FullName.Substring($RepositoryRoot.Length+1).Replace('\','/');sha256=(Get-FileHash -LiteralPath $snapshot.FullName -Algorithm SHA256).Hash.ToLowerInvariant();bytes=$snapshot.Length}}
if(@($cases.sha256|Sort-Object -Unique).Count -ne 28){throw 'Settlement snapshots must have 28 unique hashes.'}
$evidence=[ordered]@{schemaVersion=1;evidenceType='frontend-visual-regression-baseline';generatedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceCommit=(git -C $RepositoryRoot rev-parse HEAD).Trim();contractVersion='operations-settlement-design-1.0';baselineVersion='operations-settlement-windows-chromium-v1';environment=[ordered]@{operatingSystem='Windows';browser='Chromium';viewport='1440x900';locale='zh-CN';timezone='Asia/Shanghai';colorScheme='light';reducedMotion=$true};businessAssertions=@('Fuxing Bank operations console covers 28 clearing, reconciliation, and end-of-day states from PV-0136 through PV-0163.','Clearing monitoring aggregates persisted clearing_payment and transfer_order records and does not expose an unsupported artificial batch trigger.','Reconciliation executes three real ledger paths and persists difference results.','End-of-day processing uses a database transaction lock and idempotency key so repeated requests do not create duplicate runs.','The source images for PV0138 and PV0147 conflict with their filename states; the baseline follows filename state, the unified operations shell, and the real business contract.','Visual fixtures are deterministic synthetic data and contain no real personal data or secrets.');cases=$cases}
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $outputPath)|Out-Null;$utf8NoBom=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText($outputPath,($evidence|ConvertTo-Json -Depth 8),$utf8NoBom);Write-Output $outputPath
